    const n = grid[0].length;

    const dp = Array.from({ length: m - k + 1 }, () => Array.from({ length: n - k + 1 }, () => new Set()));

    for (let row = 0; row < m - k + 1; row++) {
        for (let col = 0; col < n - k + 1; col++) {
