var minAbsDiff = function(grid, k) {
    const m = grid.length;
    const n = grid[0].length;

    const dp = Array.from({ length: m - k + 1 }, () => Array(n - k + 1).fill(0));

    for (let row = 0; row < m - k + 1; row++) {
        for (let col = 0; col < n - k + 1; col++) {
            const set = new Set();

            for (let r = 0; r < k; r++) {
                for (let c = 0; c < k; c++) {
                    set.add(grid[row + r][col + c]);
                }
            }

            const arr = [...set];

            if (arr.length <= 1) {
                continue;
            }

            arr.sort((a, b) => a - b);

            let minDiff = Infinity;

            for (let pos = 1; pos < arr.length; pos++) {
                minDiff = Math.min(minDiff, Math.abs(arr[pos] - arr[pos - 1]));
            }

            dp[row][col] = minDiff;
        }
    }

    return dp;
};
